70	@RestController
71	@CrossOrigin(exposedHeaders = "errors, content-type")
72	@RequestMapping("/api")
73	public class OwnerRestControllerV1 implements OwnersApi {
74	
75	    /**
76	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that
77	     * contains at least one dot, with no whitespace anywhere. Deliberately lenient — it accepts
78	     * ordinary addresses while rejecting clearly malformed ones such as {@code not-an-email}.
79	     */
80	    private static final Pattern EMAIL_PATTERN =
81	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
82	
83	    /**
84	     * Dedicated audit logger. On a successful create an audit line carrying the owner id, the
85	     * customerCode, the registrationDate and the membershipLevel is emitted through this logger.
86	     */
87	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
88	
89	    private final ClinicService clinicService;
90	
91	    private final OwnerMapper ownerMapper;
92	
93	    private final PetMapper petMapper;
94	
95	    private final VisitMapper visitMapper;
