122	    /**
123	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
124	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
125	     */
126	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
127	        List<String> missing = new ArrayList<>();
128	        if (isBlank(ownerFieldsDto.getFirstName())) {
129	            missing.add("firstName");
130	        }
131	        if (isBlank(ownerFieldsDto.getLastName())) {
132	            missing.add("lastName");
133	        }
134	        if (isBlank(ownerFieldsDto.getAddress())) {
135	            missing.add("address");
136	        }
137	        if (isBlank(ownerFieldsDto.getCity())) {
138	            missing.add("city");
139	        }
140	        if (isBlank(ownerFieldsDto.getTelephone())) {
141	            missing.add("telephone");
142	        }
143	        if (!missing.isEmpty()) {
144	            throw new RequiredFieldsMissingException(missing);
145	        }
146	    }
147	
148	    private static boolean isBlank(String value) {
149	        return value == null || value.isBlank();
150	    }
151	
152	    /**
153	     * Normalizes an address on create: leading/trailing whitespace is trimmed, every run of internal
154	     * whitespace is collapsed to a single space, the value is upper-cased and common abbreviations are
155	     * expanded token-by-token ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The
156	     * normalized value is what gets stored, returned and used for every address comparison; a value
157	     * that is blank (or {@code null}) normalizes to the empty string so the required-field check
158	     * rejects it.
159	     *
160	     * @param address the raw address as supplied by the caller, may be {@code null}
161	     * @return the normalized address ({@code ""} when blank or {@code null})
162	     */
163	    private static String normalizeAddress(String address) {
164	        if (address == null) {
165	            return "";
166	        }
167	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
168	        if (collapsed.isEmpty()) {
169	            return "";
170	        }
171	        String[] tokens = collapsed.split(" ");
172	        StringBuilder sb = new StringBuilder(collapsed.length());
173	        for (int i = 0; i < tokens.length; i++) {
174	            String token = tokens[i];
175	            switch (token) {
176	                case "ST" -> token = "STREET";
177	                case "RD" -> token = "ROAD";
178	                case "AVE" -> token = "AVENUE";
179	                default -> { }
180	            }
181	            if (i > 0) {
182	                sb.append(' ');
183	            }
184	            sb.append(token);
185	        }
186	        return sb.toString();
187	    }
188	
189	    /**
190	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
191	     * A leading {@code +} and its country code are kept as given; otherwise the country code
192	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
193	     * The result must carry 8 to 15 digits after the {@code +}. In addition, when the country code
194	     * is recognized the national number must have the exact length that code requires ({@code +61}
195	     * expects 9 national digits, {@code +1} expects 10). Returns the E.164 string to be stored and
196	     * returned.
197	     *
198	     * @param telephone the raw telephone as supplied by the caller
199	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
200	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
201	     *     national-number length is wrong for its country code
202	     */
203	    private static String normalizeTelephone(String telephone) {
204	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
205	        String e164;
206	        if (cleaned.startsWith("+")) {
207	            e164 = "+" + cleaned.substring(1);
208	        } else {
209	            String national = cleaned;
210	            if (national.startsWith("0")) {
211	                national = national.substring(1);
212	            }
213	            e164 = "+61" + national;
214	        }
215	        String digits = e164.substring(1);
216	        if (!digits.matches("\\d{8,15}")) {
217	            throw new InvalidTelephoneException(
218	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
219	        }
220	        if (digits.startsWith("61")) {
221	            requireNationalLength(digits.substring(2), 9, "+61");
222	        } else if (digits.startsWith("1")) {
223	            requireNationalLength(digits.substring(1), 10, "+1");
224	        }
225	        return e164;
226	    }
227	
228	    /**
229	     * Enforces that the national portion of an E.164 number has the exact number of digits its
230	     * country code requires.
231	     *
232	     * @param national the national-number digits (the part after the country code)
233	     * @param expected the exact national-number length the country code requires
234	     * @param countryCode the country code, for the error message
235	     * @throws InvalidTelephoneException if {@code national} does not have exactly {@code expected} digits
236	     */
237	    private static void requireNationalLength(String national, int expected, String countryCode) {
238	        if (national.length() != expected) {
239	            throw new InvalidTelephoneException(
240	                "Telephone with country code '" + countryCode + "' must have " + expected
241	                    + " national digits");
242	        }
243	    }
244	
245	    /**
246	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
247	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
248	     *
249	     * @param email the raw email as supplied by the caller, may be {@code null}
250	     * @return the lower-cased email, or {@code null} when none was supplied
251	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
252	     */
253	    private static String normalizeEmail(String email) {
254	        if (email == null || email.isBlank()) {
255	            return null;
256	        }
257	        String trimmed = email.trim();
258	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
259	            throw new InvalidEmailException("Email must be a syntactically valid address");
260	        }
261	        return trimmed.toLowerCase(Locale.ROOT);
262	    }
263	
264	    /**
265	     * Rejects a create whose E.164 telephone is already used by any existing owner, so that
266	     * telephones stay unique across owners. Telephones are stored in E.164 form on create, so a
267	     * direct equality comparison of the E.164 values against the stored values is sufficient.
268	     *
269	     * @param normalizedTelephone the E.164 telephone of the owner being created
270	     * @throws DuplicateTelephoneException if another owner already uses this telephone
271	     */
272	    private void rejectDuplicateTelephone(String normalizedTelephone) {
273	        boolean inUse = this.clinicService.findAllOwners().stream()
274	            .anyMatch(existing -> normalizedTelephone.equals(existing.getTelephone()));
275	        if (inUse) {
276	            throw new DuplicateTelephoneException(
277	                "Telephone is already used by another owner");
278	        }
279	    }
280	
281	    /**
282	     * Rejects a create whose email is already used by any existing owner, so that emails stay unique
283	     * across owners. Emails are compared case-insensitively: the supplied value is already lower-cased
284	     * by {@link #normalizeEmail}, and each stored value is lower-cased before comparison, so
285	     * {@code 'Jane@Example.com'} and {@code 'jane@example.com'} are treated as the same email. A create
286	     * with no email ({@code null}) is never rejected on this basis.
287	     *
288	     * @param normalizedEmail the lower-cased email of the owner being created, may be {@code null}
289	     * @throws DuplicateEmailException if another owner already uses this email
290	     */
291	    private void rejectDuplicateEmail(String normalizedEmail) {
292	        if (normalizedEmail == null) {
293	            return;
294	        }
295	        boolean inUse = this.clinicService.findAllOwners().stream()
296	            .map(Owner::getEmail)
297	            .filter(Objects::nonNull)
298	            .anyMatch(existing -> normalizedEmail.equals(existing.toLowerCase(Locale.ROOT)));
299	        if (inUse) {
300	            throw new DuplicateEmailException(
301	                "Email is already used by another owner");
302	        }
303	    }
304	
305	    /**
306	     * Rejects a create that would place the owner in a household already occupied by another owner,
307	     * i.e. one whose last name and address match the supplied values. The two fields are compared
308	     * case-insensitively after whitespace is collapsed (leading/trailing whitespace trimmed and each
309	     * run of internal whitespace reduced to a single space), so {@code '110 W.  Liberty St. '} and
310	     * {@code '110 w. liberty st.'} are treated as the same address. The caller may bypass this check
311	     * by setting {@code sharesHousehold} to {@code true}.
312	     *
313	     * @param lastName the last name of the owner being created
314	     * @param address the address of the owner being created
315	     * @throws DuplicateHouseholdException if another owner already shares this last name and address
316	     */
317	    private void rejectDuplicateHousehold(String lastName, String address) {
318	        String normalizedLastName = normalizeForHousehold(lastName);
319	        String normalizedAddress = normalizeForHousehold(address);
320	        boolean inHousehold = this.clinicService.findAllOwners().stream()
321	            .anyMatch(existing ->
322	                normalizedLastName.equals(normalizeForHousehold(existing.getLastName()))
323	                    && normalizedAddress.equals(normalizeForHousehold(existing.getAddress())));
324	        if (inHousehold) {
325	            throw new DuplicateHouseholdException(
326	                "An owner with the same last name and address already exists");
327	        }
328	    }
329	
330	    /**
331	     * Normalizes a value for household comparison by trimming, collapsing every run of whitespace to
332	     * a single space and lower-casing, so the comparison is case-insensitive with collapsed whitespace.
333	     *
334	     * @param value the raw value, may be {@code null}
335	     * @return the normalized value ({@code ""} when {@code value} is {@code null})
336	     */
337	    private static String normalizeForHousehold(String value) {
338	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
339	    }
340	
341	    /**
342	     * Derives the stable household identifier for an owner from the normalized last name and address.
343	     * The value is a deterministic function of those two fields (compared case-insensitively with
344	     * collapsed whitespace, exactly as {@link #rejectDuplicateHousehold}), so every owner in the same
345	     * household — including owners who knowingly join it via {@code sharesHousehold} — is assigned the
346	     * same identifier without any existing record having to be updated. Formatted {@code 'HH-<HEX12>'}
347	     * where {@code HEX12} is the upper-cased first twelve hex characters of the SHA-256 of the two
348	     * normalized fields.
349	     *
350	     * @param lastName the last name of the owner being created
351	     * @param address the address of the owner being created
352	     * @return the stable household identifier
353	     */
354	    private static String householdId(String lastName, String address) {
355	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
356	        try {
357	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
358	            StringBuilder sb = new StringBuilder(digest.length * 2);
359	            for (byte b : digest) {
360	                sb.append(String.format("%02x", b));
361	            }
362	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
363	        } catch (NoSuchAlgorithmException e) {
364	            throw new IllegalStateException("SHA-256 not available", e);
365	        }
366	    }
367	
368	    /**
369	     * The maximum number of owners a single city may contain. A create whose city already holds this
370	     * many owners is rejected, so a city never grows beyond this capacity.
371	     */
372	    private static final int CITY_CAPACITY = 50;
373	
374	    /**
375	     * Rejects a create whose city already contains {@link #CITY_CAPACITY} or more owners, so no city
376	     * ever exceeds its capacity. Cities are compared case-insensitively with surrounding whitespace
377	     * trimmed, exactly as {@link #nextCustomerCode} counts a city's owners. The count reflects the
378	     * state before the new owner is persisted, so it excludes the owner being created.
379	     *
380	     * @param city the city of the owner being created
381	     * @throws CityAtCapacityException if the city already contains {@link #CITY_CAPACITY} owners
382	     */
383	    private void rejectCityAtCapacity(String city) {
384	        String normalizedCity = normalizeName(city);
385	        long ownersInCity = this.clinicService.findAllOwners().stream()
386	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
387	            .count();
388	        if (ownersInCity >= CITY_CAPACITY) {
389	            throw new CityAtCapacityException(
390	                "The city already contains the maximum number of owners");
391	        }
392	    }
393	
394	    /**
395	     * The maximum number of owners that may be created on a single day. A create made once this many
396	     * owners already carry today's {@code registrationDate} is rejected, so no more than this many
397	     * owners are registered per day.
398	     */
399	    private static final int DAILY_OWNER_LIMIT = 100;
400	
401	    /**
402	     * Rejects a create once {@link #DAILY_OWNER_LIMIT} or more owners have already been created for
403	     * the given business day, counted by {@code registrationDate} equal to the effective (weekend
404	     * rolled forward) registration date of the owner being created. The count reflects the state
405	     * before the new owner is persisted, so it excludes the owner being created.
406	     *
407	     * @param registrationDate the effective business-day registration date of the owner being created
408	     * @throws DailyOwnerLimitExceededException if the day already holds {@link #DAILY_OWNER_LIMIT} owners
409	     */
410	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
411	        long ownersToday = this.clinicService.findAllOwners().stream()
412	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
413	            .count();
414	        if (ownersToday >= DAILY_OWNER_LIMIT) {
415	            throw new DailyOwnerLimitExceededException(
416	                "The maximum number of owners for today has already been reached");
417	        }
418	    }
419	
420	    /**
421	     * The number of owners that may already exist for a business day before a create is flagged with
422	     * a bulk-signup warning. Once more than this many owners already carry the effective registration
423	     * date, the created owner's {@code bulkSignupWarning} is set to {@code true}.
424	     */
425	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
426	
427	    /**
428	     * Determines whether a create should be flagged with a bulk-signup warning, i.e. whether more than
429	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for the given business day,
430	     * counted by {@code registrationDate} equal to the effective (weekend rolled forward) registration
431	     * date of the owner being created. The count reflects the state before the new owner is persisted,
432	     * so it excludes the owner being created.
433	     *
434	     * @param registrationDate the effective business-day registration date of the owner being created
435	     * @return {@code true} when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the date
436	     */
437	    private boolean bulkSignupWarning(LocalDate registrationDate) {
438	        long ownersToday = this.clinicService.findAllOwners().stream()
439	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
440	            .count();
441	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
442	    }
443	
444	    /**
445	     * Rolls a registration date forward to a business day: a Saturday or Sunday is advanced to the
446	     * following Monday, any weekday is returned unchanged.
447	     *
448	     * @param date the effective registration date, supplied or defaulted to the server date
449	     * @return the same date when it is a weekday, otherwise the next Monday
450	     */
451	    private static LocalDate toBusinessDay(LocalDate date) {
452	        DayOfWeek dayOfWeek = date.getDayOfWeek();
453	        if (dayOfWeek == DayOfWeek.SATURDAY) {
454	            return date.plusDays(2);
455	        }
456	        if (dayOfWeek == DayOfWeek.SUNDAY) {
457	            return date.plusDays(1);
458	        }
459	        return date;
460	    }
461	
462	    /**
463	     * Builds the customer code assigned to an owner on create, formatted
464	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first three letters
465	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last
466	     * name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
467	     * current number of owners already in that city, e.g. {@code 'MEL-SMI-0007'}.
468	     *
469	     * @param city the city of the owner being created
470	     * @param lastName the last name of the owner being created
471	     * @return the formatted customer code
472	     */
473	    private String nextCustomerCode(String city, String lastName) {
474	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
475	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
476	        String normalizedCity = normalizeName(city);
477	        int sequence = (int) this.clinicService.findAllOwners().stream()
478	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
479	            .count() + 1;
480	        return String.format("%s-%s-%04d", city3, last3, sequence);
481	    }
482	
483	    /**
484	     * Counts the existing owners that share the owner-to-be's first and last name, compared
485	     * case-insensitively (surrounding whitespace trimmed). The count reflects the state before the
486	     * new owner is persisted, so it excludes the owner being created.
487	     *
488	     * @param firstName the first name of the owner being created
489	     * @param lastName the last name of the owner being created
490	     * @return the number of existing owners with the same first and last name
491	     */
492	    private int countNamesakes(String firstName, String lastName) {
493	        String normalizedFirstName = normalizeName(firstName);
494	        String normalizedLastName = normalizeName(lastName);
495	        return (int) this.clinicService.findAllOwners().stream()
496	            .filter(existing ->
497	                normalizedFirstName.equals(normalizeName(existing.getFirstName()))
498	                    && normalizedLastName.equals(normalizeName(existing.getLastName())))
499	            .count();
500	    }
501	
502	    /**
503	     * Counts the members of the owner-to-be's household after this create, i.e. one more than the
504	     * number of existing owners already carrying the same {@code householdId}. Because the household
505	     * identifier is a deterministic function of the normalized last name and address, every owner in
506	     * the household — including those who knowingly join it via {@code sharesHousehold} — shares the
507	     * identifier, so a direct equality count over the stored identifiers is sufficient. The count
508	     * includes the owner being created (hence the {@code + 1}).
509	     *
510	     * @param householdId the stable household identifier of the owner being created
511	     * @return the number of household members after this create (always at least 1)
512	     */
513	    private int householdSize(String householdId) {
514	        return (int) this.clinicService.findAllOwners().stream()
515	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
516	            .count() + 1;
517	    }
518	
519	    /**
520	     * Normalizes a name for case-insensitive comparison by trimming surrounding whitespace and
521	     * lower-casing.
522	     *
523	     * @param value the raw name, may be {@code null}
524	     * @return the normalized name ({@code ""} when {@code value} is {@code null})
525	     */
526	    private static String normalizeName(String value) {
527	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
528	    }
529	
530	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
531	    @Override
532	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
533	        Owner owner = this.clinicService.findOwnerById(ownerId);
534	        if (owner == null) {
535	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
536	        }
537	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
538	    }
539	
540	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
541	    @Override
542	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
543	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
544	        validateRequiredFields(ownerFieldsDto);
545	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
546	        if (registrationDate == null) {
547	            registrationDate = LocalDate.now();
548	        }
549	        registrationDate = toBusinessDay(registrationDate);
550	        ownerFieldsDto.setRegistrationDate(registrationDate);
551	        rejectDailyOwnerLimit(registrationDate);
552	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
553	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
554	        }
555	        rejectCityAtCapacity(ownerFieldsDto.getCity());
556	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
557	        rejectDuplicateTelephone(normalizedTelephone);
558	        ownerFieldsDto.setTelephone(normalizedTelephone);
559	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
560	        rejectDuplicateEmail(normalizedEmail);
561	        ownerFieldsDto.setEmail(normalizedEmail);
562	        HttpHeaders headers = new HttpHeaders();
563	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
564	        owner.setCustomerCode(nextCustomerCode(ownerFieldsDto.getCity(), ownerFieldsDto.getLastName()));
565	        String ownerHouseholdId = householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
566	        owner.setHouseholdId(ownerHouseholdId);
567	        owner.setHouseholdSize(householdSize(ownerHouseholdId));
568	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
569	        owner.setBulkSignupWarning(bulkSignupWarning(registrationDate));
570	        this.clinicService.saveOwner(owner);
571	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
572	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
573	            ownerMapper.membershipLevel(owner));
574	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
575	        headers.setLocation(UriComponentsBuilder.newInstance()
576	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
577	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
578	    }
579	
580	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
581	    @Override
582	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
583	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
584	        if (currentOwner == null) {
585	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
586	        }
587	        currentOwner.setAddress(ownerFieldsDto.getAddress());
588	        currentOwner.setCity(ownerFieldsDto.getCity());
589	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
590	        currentOwner.setLastName(ownerFieldsDto.getLastName());
591	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
592	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
593	        this.clinicService.saveOwner(currentOwner);
594	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
595	    }
596	
597	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
598	    @Transactional
599	    @Override
600	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
601	        Owner owner = this.clinicService.findOwnerById(ownerId);
602	        if (owner == null) {
603	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
604	        }
605	        this.clinicService.deleteOwner(owner);
606	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
607	    }
608	
609	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
610	    @Override
611	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
612	        Owner owner = this.clinicService.findOwnerById(ownerId);
613	        if (owner == null) {
614	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
615	        }
616	        HttpHeaders headers = new HttpHeaders();
617	        Pet pet = petMapper.toPet(petFieldsDto);
618	        owner.setId(ownerId);
619	        pet.setOwner(owner);
620	        pet.getType().setName(null);
621	        this.clinicService.savePet(pet);
622	        PetDto petDto = petMapper.toPetDto(pet);
623	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
624	            .buildAndExpand(pet.getId()).toUri());
625	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
626	    }
627	
628	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
629	    @Override
630	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
631	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
632	        if (currentOwner != null) {
633	            Pet currentPet = this.clinicService.findPetById(petId);
634	            if (currentPet != null) {
635	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
636	                currentPet.setName(petFieldsDto.getName());
637	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
638	                this.clinicService.savePet(currentPet);
639	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
640	            }
641	        }
642	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
643	    }
644	
645	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
646	    @Override
647	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
648	        HttpHeaders headers = new HttpHeaders();
649	        Visit visit = visitMapper.toVisit(visitFieldsDto);
650	        Pet pet = new Pet();
651	        pet.setId(petId);
652	        visit.setPet(pet);
653	        this.clinicService.saveVisit(visit);
654	        VisitDto visitDto = visitMapper.toVisitDto(visit);
655	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
656	            .buildAndExpand(visit.getId()).toUri());
657	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
658	    }
659	
660	
661	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
662	    @Override
663	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
664	        Owner owner = this.clinicService.findOwnerById(ownerId);
665	        if (owner != null) {
666	            Pet pet = owner.getPet(petId);
667	            if (pet != null) {
668	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
669	            }
670	        }
671	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
672	    }
