16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
25	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
26	    @Mapping(target = "locality", expression = "java(locality(owner))")
27	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
28	    OwnerDto toOwnerDto(Owner owner);
29	
30	    /**
31	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is present,
32	     * otherwise {@code PHONE}.
33	     */
34	    default OwnerDto.@Nullable ContactPreferenceEnum contactPreference(@Nullable Owner owner) {
35	        if (owner == null) {
36	            return null;
37	        }
38	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
39	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
40	    }
41	
42	    /**
43	     * Canonical region -> city table, used to derive an owner's locality.
44	     */
45	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
46	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
47	
48	    /**
49	     * Derives the owner's locality from the city using the fixed city-to-region table
50	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), returning the canonical region string
51	     * or {@code 'UNKNOWN'} when the city is not in the table.
52	     */
53	    default @Nullable String locality(@Nullable Owner owner) {
54	        if (owner == null) {
55	            return null;
56	        }
57	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
58	    }
